-- ----------------------------



-- Table structure for cms_agreement



-- ----------------------------



DROP TABLE IF EXISTS `cms_agreement`;



CREATE TABLE `cms_agreement` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',



  `document` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协议标识(userregister/userprivacy/points-withdrawal-rules/...)',



  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协议标题',



  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '协议内容(HTML富文本)',



  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(1启用/0禁用)',



  `version` int NOT NULL DEFAULT '1' COMMENT '版本号(预留,历史留痕二期)',



  `effective_time` datetime DEFAULT NULL COMMENT '生效时间(预留)',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除(0正常/1删除)',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `uk_document` (`document`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='协议/条款(内容域)';







-- ----------------------------



-- Records of cms_agreement



-- ----------------------------



BEGIN;









COMMIT;







