-- Table structure for cms_article



-- ----------------------------



DROP TABLE IF EXISTS `cms_article`;



CREATE TABLE `cms_article` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文章id',



  `title` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',



  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '简介/描述',



  `category_id` bigint NOT NULL DEFAULT '0' COMMENT '分类id(cms_article_category)',



  `title_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '标题颜色(十六进制)',



  `jump_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '外链跳转地址(非空时详情跳外链)',



  `is_enable` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用(1是/0否)',



  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '正文HTML',



  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '封面URL',



  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '图集JSON(一维url数组)',



  `access_count` int NOT NULL DEFAULT '0' COMMENT '访问量',



  `share_images` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '分享图URL',



  `seo_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'SEO标题',



  `seo_keywords` varchar(130) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'SEO关键字',



  `seo_desc` varchar(230) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'SEO描述',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除(0正常/1删除)',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_category` (`category_id`) USING BTREE,



  KEY `idx_enable` (`is_enable`) USING BTREE,



  KEY `idx_access` (`access_count`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='文章';







