-- Table structure for cms_custom_view



-- ----------------------------



DROP TABLE IF EXISTS `cms_custom_view`;



CREATE TABLE `cms_custom_view` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',



  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'logo图片URL',



  `name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '页面名称',



  `html_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '页面HTML代码(整页内容,app 用 mp-html 渲染)',



  `css_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT 'CSS样式(预留,app 端 mp-html 不执行,web 用)',



  `js_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT 'JS代码(预留,app 端不执行,web 用)',



  `is_enable` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用(1是/0否)',



  `is_header` tinyint NOT NULL DEFAULT '1' COMMENT '是否包含头部(1是/0否,app 显示搜索栏)',



  `is_footer` tinyint NOT NULL DEFAULT '1' COMMENT '是否包含尾部(1是/0否,app 显示底部分隔)',



  `is_full_screen` tinyint NOT NULL DEFAULT '0' COMMENT '是否满屏(1是/0否,预留)',



  `access_count` int NOT NULL DEFAULT '0' COMMENT '访问量',



  `seo_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'SEO标题',



  `seo_keywords` varchar(130) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'SEO关键字',



  `seo_desc` varchar(230) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'SEO描述',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除(0正常/1删除)',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_name` (`name`) USING BTREE,



  KEY `idx_enable` (`is_enable`) USING BTREE,



  KEY `idx_access` (`access_count`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='自定义页面(内容域,ShopXO sxo_custom_view 迁移)';







