  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '视频标题',



  `cover` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',



  `video_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '视频地址URL(mp4/hls)',



  `duration` int NOT NULL DEFAULT '0' COMMENT '时长(秒)',



  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '简介',



  `access_count` int NOT NULL DEFAULT '0' COMMENT '浏览数',



  `is_recommended` tinyint NOT NULL DEFAULT '0' COMMENT '是否推荐(1是/0否)',



  `is_hot` tinyint NOT NULL DEFAULT '0' COMMENT '是否热门(1是/0否)',



  `sort` int NOT NULL DEFAULT '0',



  `is_enable` tinyint NOT NULL DEFAULT '1',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,



  `deleted` tinyint NOT NULL DEFAULT '0',



  `spu_id` bigint DEFAULT NULL COMMENT '关联商品SPU(0/null=不挂)',



