  `spu_pic` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品主图快照',



  `spu_price` decimal(10,2) DEFAULT NULL COMMENT '商品价格快照',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_enable_sort` (`is_enable`,`sort`) USING BTREE



