-- Table structure for mq_message_process



-- ----------------------------



DROP TABLE IF EXISTS `mq_message_process`;



CREATE TABLE `mq_message_process` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',



  `message_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息ID',



  `exchange` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '消息类型',



  `routing_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '消息类型',



  `consumer_queue` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '消费队列',



  `message_body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '消息体',



  `business_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '业务ID',



  `message_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '消息类型',



  `source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '消息类型',



  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '0' COMMENT '状态：0-处理中 1-处理成功 2-处理失败',



  `retry_count` int DEFAULT '0' COMMENT '重试次数',



  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '错误信息',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `uk_message_id` (`message_id`) USING BTREE,



  UNIQUE KEY `udx_business_id` (`business_id`,`message_type`) USING BTREE,



  KEY `idx_message_type` (`message_type`) USING BTREE,



  KEY `idx_consumer_queue` (`consumer_queue`) USING BTREE,



  KEY `idx_status` (`status`) USING BTREE,



  KEY `idx_create_time` (`create_time`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=6943642 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='消息处理日志表';







