-- Table structure for oms_logistics_info



-- ----------------------------



DROP TABLE IF EXISTS `oms_logistics_info`;



CREATE TABLE `oms_logistics_info` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',



  `biz_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务单号',



  `logistics_type` tinyint(1) NOT NULL COMMENT '物流类型 1-发货物流，2-退货物流',



  `tracking_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物流单号',



  `carrier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物流公司编码',



  `carrier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物流公司名称',



  `phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '收件人手机号',



  `status` int NOT NULL COMMENT '物流状态',



  `query_count` bigint DEFAULT '0' COMMENT '补偿查询次数',



  `last_query_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '最后查询时间',



  `last_callback_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '最后回调时间',



  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `idx_tracking_no` (`tracking_no`) USING BTREE,



  KEY `idx_carrier_code` (`carrier_code`) USING BTREE,



  KEY `idx_order_id` (`biz_no`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='物流轨迹表';







