-- Table structure for oms_order



-- ----------------------------



DROP TABLE IF EXISTS `oms_order`;



CREATE TABLE `oms_order` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',



  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单号',



  `order_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'NORMAL' COMMENT '订单类型',



  `order_scene` varchar(50) DEFAULT NULL COMMENT '订单场景',



  `total_amount` decimal(12,2) DEFAULT '0.00' COMMENT '订单总额(元)',



  `total_retail_price` decimal(12,2) DEFAULT '0.00' COMMENT '零售总价(元)',



  `total_supply_price` decimal(20,2) DEFAULT '0.00' COMMENT '供货总价(元)',



  `mch_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付商户编号',



  `total_quantity` int DEFAULT '0' COMMENT '商品总数',



  `source` int DEFAULT '1' COMMENT '订单来源(0-PC订单；1-app订单)',



  `status` int DEFAULT '1' COMMENT '订单状态(0-待付款;1-待发货;2-待收货;3-已完成;4-已取消;5-售后中;6-已退款)',



  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '订单备注',



  `member_id` bigint NOT NULL COMMENT '会员ID',



  `coupon_id` bigint DEFAULT NULL COMMENT '使用的优惠券ID',



  `coupon_amount` decimal(12,2) DEFAULT '0.00' COMMENT '优惠券抵扣金额(元)',



  `freight_amount` decimal(12,2) DEFAULT '0.00' COMMENT '运费金额(元)',



  `payment_amount` decimal(12,2) DEFAULT '0.00' COMMENT '应付总额(元)',



  `use_points_amount` decimal(18,2) DEFAULT '0.00' COMMENT '积分使用金额(元)',



  `points_deduction_amount` decimal(12,2) DEFAULT '0.00' COMMENT '积分抵扣金额(元)',



  `payment_time` datetime DEFAULT NULL COMMENT '支付时间',



  `pay_channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '支付方式【1->微信jsapi；2->支付宝；3->余额；4->微信app；】',



  `payment_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '业务支付单号：关联的业务层支付单号 (oms_payment.payment_no)',



  `payment_channel_no` varchar(64) DEFAULT NULL COMMENT '支付申请号（渠道请求号）',



  `channel_trade_no` varchar(64) DEFAULT NULL COMMENT '渠道交易号（微信transaction_id/支付宝trade_no），用于对账',



  `payment_discount_amount` decimal(12,2) DEFAULT '0.00' COMMENT '支付抵扣金额(元)',



  `delivery_time` datetime DEFAULT NULL COMMENT '发货时间',



  `receive_time` datetime DEFAULT NULL COMMENT '确认收货时间',



  `share_user_id` bigint DEFAULT NULL COMMENT '分享用户ID',



  `shop_id` bigint DEFAULT NULL COMMENT '店铺ID(下单快照)',



  `shop_name` varchar(64) DEFAULT NULL COMMENT '店铺名称(下单快照)',



  `deleted` int DEFAULT '0' COMMENT '逻辑删除标识(0:正常；1:已删除)',



  `cancel_time` datetime DEFAULT NULL COMMENT '取消时间',



  `refund_time` datetime DEFAULT NULL COMMENT '退款时间',



  `need_delivery` tinyint(1) DEFAULT '1' COMMENT '是否需要发货：0-不需要 1-需要',



  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `channel_user_id` varchar(128) DEFAULT NULL COMMENT '渠道用户标识(微信openid等)',



  `buyer_phone` varchar(20) DEFAULT NULL COMMENT '下单人手机号（快照，下单时从 JWT 冗余）',



  `channel` varchar(32) DEFAULT NULL COMMENT 'è®¢å•æ¸ é“(APP/H5/MINI/PC)',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `order_no` (`order_no`) USING BTREE,



  KEY `idx_order_no` (`order_no`) USING BTREE,



  KEY `idx_member_id` (`member_id`) USING BTREE,



  KEY `idx_status` (`status`) USING BTREE,



  KEY `idx_payment_no` (`payment_no`) USING BTREE,



  KEY `idx_deleted` (`deleted`) USING BTREE,



  KEY `idx_create_time` (`create_time`) USING BTREE,



  KEY `idx_update_time` (`update_time`) USING BTREE,



  KEY `idx_use_balance_points` (`use_points_amount`) USING BTREE,



  KEY `idx_oms_order_buyer_phone` (`buyer_phone`)



) ENGINE=InnoDB AUTO_INCREMENT=668 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单主表';







