-- Table structure for oms_order_address



-- ----------------------------



DROP TABLE IF EXISTS `oms_order_address`;



CREATE TABLE `oms_order_address` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',



  `receive_address_id` bigint DEFAULT NULL COMMENT '收货地址id',



  `receive_address_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'USER_RECEIVE' COMMENT 'MERCHANT_RECEIVE:商家收货(用于售后)，USER_RECEIVE:用户收货',



  `order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单号',



  `order_id` bigint NOT NULL COMMENT '订单id',



  `order_item_id` bigint DEFAULT NULL COMMENT '订单商品id：用于售后，商家发货时无效',



  `user_id` bigint NOT NULL COMMENT '收货地址用户id',



  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '收货地址用户名字',



  `user_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '收货地址用户手机号',



  `zip_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '邮编',



  `province_id` int DEFAULT '0' COMMENT '省',



  `city_id` int DEFAULT '0' COMMENT '市',



  `area_id` int DEFAULT '0' COMMENT '区',



  `province_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '省份',



  `city_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '市',



  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '区',



  `address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '地址',



  `complete_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '完整地址',



  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',



  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '删除标识 0 - 未删除  1- 已删除',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_order_id` (`order_id`) USING BTREE,



  KEY `idx_order_item_id` (`order_item_id`) USING BTREE,



  KEY `idx_new_health_order_receive_address01` (`user_id`) USING BTREE,



  KEY `idx_new_health_order_receive_address02` (`receive_address_id`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=672 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单收货地址';







