-- Table structure for oms_order_after_sale



-- ----------------------------



DROP TABLE IF EXISTS `oms_order_after_sale`;



CREATE TABLE `oms_order_after_sale` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '售后ID',



  `after_sale_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '售后单号',



  `order_id` bigint NOT NULL COMMENT '订单ID',



  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单编号',



  `member_id` bigint NOT NULL COMMENT '用户ID',



  `supplier_id` bigint NOT NULL COMMENT '供应商ID',



  `supplier_name` varchar(64) DEFAULT NULL COMMENT '供应商名称(下单快照)',



  `shop_id` bigint DEFAULT NULL COMMENT '店铺ID(下单快照)',



  `shop_name` varchar(64) DEFAULT NULL COMMENT '店铺名称(下单快照)',



  `after_sale_type` tinyint(1) NOT NULL COMMENT '售后类型(1-仅退款，2-退货退款)',



  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '申请原因',



  `apply_pics` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '凭证图片，多个以逗号分隔',



  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '问题描述',



  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '售后状态',



  `handle_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '处理人',



  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',



  `handle_note` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '处理备注',



  `tracking_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '退货物流单号',



  `carrier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '退货物流公司',



  `carrier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '退货物流公司',



  `sender_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '发货人手机号',



  `return_pics` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '退货凭证图片，多个以逗号分隔',



  `return_time` datetime DEFAULT NULL COMMENT '退货时间',



  `receive_time` datetime DEFAULT NULL COMMENT '收货时间',



  `refund_amount` decimal(12,2) DEFAULT '0.00' COMMENT '退款金额(元)',



  `refund_time` datetime DEFAULT NULL COMMENT '退款提交时间',



  `refund_success_time` datetime DEFAULT NULL COMMENT '退款到账时间',



  `refund_type` tinyint(1) DEFAULT NULL COMMENT '退款方式(1->支付宝; 2->微信; 3->银联; 4->原路返回)',



  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除(0->正常; 1->已删除)',



  `use_points_amount` decimal(18,2) DEFAULT '0.00' COMMENT '积分使用金额(元)',



  `order_item_id` bigint DEFAULT NULL COMMENT '订单商品行ID(一售后单=一商品行,与明细一致)',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `idx_after_sale_no` (`after_sale_no`) USING BTREE,



  KEY `idx_order_id` (`order_id`) USING BTREE,



  KEY `idx_order_no` (`order_no`) USING BTREE,



  KEY `idx_user_id` (`member_id`) USING BTREE,



  KEY `idx_order_item_id` (`order_item_id`)



) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单售后表';







