DROP TABLE IF EXISTS `oms_order_after_sale_item`;



CREATE TABLE `oms_order_after_sale_item` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '售后商品ID',



  `after_sale_id` bigint NOT NULL COMMENT '售后ID',



  `order_item_id` bigint NOT NULL COMMENT '订单商品ID',



  `spu_id` bigint NOT NULL COMMENT '商品ID',



  `sku_id` bigint NOT NULL COMMENT '商品SKU ID',



  `sku_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '商品编码',



  `sku_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品名称',



  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '商品图片',



  `quantity` int NOT NULL COMMENT '申请数量',



  `price` decimal(12,2) DEFAULT '0.00' COMMENT '商品单价(元)',



  `retail_price` decimal(12,2) DEFAULT NULL COMMENT '零售价(元)',



  `supply_price` decimal(12,2) DEFAULT NULL COMMENT '供货价(元)',



  `total_amount` decimal(12,2) DEFAULT '0.00' COMMENT '退款金额(元)',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `pre_status` tinyint NOT NULL DEFAULT '0' COMMENT '售后申请时商品项状态快照(1待发货/2已发货/3已收货; 0-未回填)',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_after_sale_id` (`after_sale_id`) USING BTREE,



  KEY `idx_order_item_id` (`order_item_id`) USING BTREE,



  KEY `idx_product_id` (`spu_id`) USING BTREE,



  KEY `idx_sku_id` (`sku_id`) USING BTREE,



  CONSTRAINT `fk_after_sale_item_after_sale_id` FOREIGN KEY (`after_sale_id`) REFERENCES `oms_order_after_sale` (`id`) ON DELETE CASCADE ON UPDATE CASCADE



) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单售后商品明细表';







