DROP TABLE IF EXISTS `oms_order_delivery`;



CREATE TABLE `oms_order_delivery` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',



  `order_id` bigint NOT NULL COMMENT '订单id',



  `tracking_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物流单号',



  `carrier_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物流公司编码',



  `carrier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '物流单号',



  `status` tinyint DEFAULT '0' COMMENT '物流状态【0->运输中；1->已收货】',



  `delivery_type` tinyint DEFAULT '1' COMMENT '发货类型：1线上物流 2线下发货',



  `delivery_time` datetime DEFAULT NULL COMMENT '发货时间',



  `complete_time` datetime DEFAULT NULL COMMENT '确认收货时间',



  `create_time` datetime DEFAULT NULL COMMENT '创建时间',



  `update_time` datetime DEFAULT NULL COMMENT '修改时间',



  `remark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '备注',



  `supplier_id` bigint DEFAULT NULL COMMENT '发货单归属供应商',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_order_id` (`order_id`) USING BTREE,



  KEY `idx_create_time` (`create_time`) USING BTREE,



  KEY `idx_carrier_no` (`tracking_no`) USING BTREE,



  KEY `idx_supplier_id` (`supplier_id`)



) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单物流记录表';







