CREATE TABLE `oms_order_delivery_item` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',



  `delivery_id` bigint NOT NULL COMMENT '发货单ID',



  `order_item_id` bigint NOT NULL COMMENT '订单商品项ID',



  `quantity` int NOT NULL DEFAULT '0' COMMENT '本发货单中的商品数量',



  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,



  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`),



  KEY `idx_delivery_id` (`delivery_id`),



  KEY `idx_order_item_id` (`order_item_id`)



) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单发货单商品明细';







