-- Table structure for oms_order_item



-- ----------------------------



DROP TABLE IF EXISTS `oms_order_item`;



CREATE TABLE `oms_order_item` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',



  `order_id` bigint NOT NULL COMMENT '订单ID',



  `spu_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '商品名称',



  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',



  `supplier_name` varchar(64) DEFAULT NULL COMMENT '供应商名称(下单快照)',



  `shop_id` bigint DEFAULT NULL COMMENT '店铺ID(下单快照)',



  `shop_name` varchar(64) DEFAULT NULL COMMENT '店铺名称(下单快照)',



  `spu_id` bigint NOT NULL DEFAULT '0' COMMENT '商品ID',



  `sku_id` bigint NOT NULL DEFAULT '0' COMMENT '规格ID',



  `sku_sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '商品编码',



  `sku_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '规格名称',



  `pic_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '商品图片',



  `price` decimal(12,2) DEFAULT '0.00' COMMENT '商品单价(元)',



  `retail_price` decimal(12,2) DEFAULT '0.00' COMMENT '零售价(元)',



  `supply_price` decimal(12,2) DEFAULT '0.00' COMMENT '供货价(元)',



  `freight_amount` decimal(12,2) DEFAULT '0.00' COMMENT '运费金额(元)',



  `freight_template_id` bigint DEFAULT NULL COMMENT '运费模板ID',



  `forbidden_area_id` bigint DEFAULT NULL COMMENT '禁售区域ID',



  `quantity` int DEFAULT NULL COMMENT '商品数量',



  `total_amount` decimal(12,2) DEFAULT '0.00' COMMENT '商品总金额(元)',



  `create_time` datetime DEFAULT NULL COMMENT '创建时间',



  `update_time` datetime DEFAULT NULL COMMENT '修改时间',



  `refund_status` tinyint NOT NULL DEFAULT '0' COMMENT '退款状态: 0-正常 1-全额退款 2-部分退款',



  `refund_quantity` int DEFAULT '0' COMMENT '退款数量',



  `refund_amount` decimal(12,2) DEFAULT '0.00' COMMENT '退款金额(元)',



  `is_commented` tinyint NOT NULL DEFAULT '0' COMMENT '是否已评论 0-否 1-是',



  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除标识(1:已删除；0:正常)',



  `status` tinyint NOT NULL DEFAULT '1' COMMENT '履约状态: 0-已取消 1-待发货 2-已发货 3-已收货 4-售后中 5-已退款',



  `coupon_deduction_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '优惠券抵扣分摊(按行金额占比,尾差最后行兜底)',



  `points_deduction_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '积分抵扣分摊',



  `payment_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '行实付 = 行商品额+行运费-Σ行抵扣',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `index_order_id` (`order_id`) USING BTREE COMMENT '订单id索引',



  KEY `idx_status` (`status`)



) ENGINE=InnoDB AUTO_INCREMENT=674 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='订单商品信息表';







