  `create_time` datetime DEFAULT NULL COMMENT '创建时间',



  `update_time` datetime DEFAULT NULL COMMENT '更新时间(新增有值)',



  PRIMARY KEY (`id`) USING BTREE



) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='广告表';







