-- Table structure for sms_coupon



-- ----------------------------



DROP TABLE IF EXISTS `sms_coupon`;



CREATE TABLE `sms_coupon` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',



  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优惠券名称',



  `type` tinyint NOT NULL DEFAULT '1' COMMENT '优惠券类型(1-满减券;2-直减券;3-折扣券)',



  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '0' COMMENT '优惠券码',



  `platform` int DEFAULT NULL COMMENT '使用平台(0-全平台;1-APP;2-PC)',



  `face_value_type` tinyint DEFAULT NULL COMMENT '优惠券面值类型',



  `face_value` bigint DEFAULT NULL COMMENT '优惠券面值(分)',



  `discount` decimal(10,2) DEFAULT NULL COMMENT '折扣',



  `min_point` bigint DEFAULT NULL COMMENT '使用门槛(0:无门槛)',



  `per_limit` int DEFAULT '1' COMMENT '每人限领张数(-1-无限制)',



  `validity_period_type` tinyint DEFAULT NULL COMMENT '有效期类型(1:自领取时起有效天数;2:有效起止时间)',



  `validity_days` int DEFAULT '1' COMMENT '有效期天数',



  `validity_begin_time` datetime DEFAULT NULL COMMENT '有效期起始时间',



  `validity_end_time` datetime DEFAULT NULL COMMENT '有效期截止时间',



  `application_scope` tinyint DEFAULT NULL COMMENT '应用范围(0-全场通用;1-指定商品分类;2-指定商品)',



  `circulation` int DEFAULT '1' COMMENT '发行量(-1-无限制)',



  `received_count` int DEFAULT '0' COMMENT '已领取的优惠券数量(统计)',



  `used_count` int DEFAULT '0' COMMENT '已使用的优惠券数量(统计)',



  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',



  `update_time` datetime DEFAULT NULL COMMENT '创建时间',



  `create_time` datetime DEFAULT NULL COMMENT '修改时间',



  `deleted` tinyint DEFAULT '1' COMMENT '逻辑删除标识(0-正常;1-删除)',



  PRIMARY KEY (`id`) USING BTREE



) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='优惠券表';







