-- Table structure for sms_live_room



-- ----------------------------



DROP TABLE IF EXISTS `sms_live_room`;



CREATE TABLE `sms_live_room` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',



  `room_no` varchar(32) NOT NULL COMMENT '直播间编号',



  `title` varchar(100) NOT NULL COMMENT '直播标题',



  `cover` varchar(255) DEFAULT NULL COMMENT '直播间封面图',



  `stream_name` varchar(64) NOT NULL COMMENT '直播流名(唯一,用于生成推拉流地址)',



  `push_url` varchar(255) DEFAULT NULL COMMENT '推流地址(RTMP,含防盗链,可重新生成)',



  `pull_url` varchar(255) DEFAULT NULL COMMENT '拉流地址(HLS前缀,前端拼.m3u8)',



  `status` tinyint NOT NULL DEFAULT '0' COMMENT '直播状态(0-未开播;1-直播中;2-主播离开;3-封禁)',



  `anchor_name` varchar(50) DEFAULT NULL COMMENT '主播昵称',



  `anchor_avatar` varchar(255) DEFAULT NULL COMMENT '主播头像',



  `online_count` int NOT NULL DEFAULT '0' COMMENT '在线人数',



  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数',



  `is_recommended` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'æ˜¯å¦é¦–é¡µæŽ¨è',



  `is_live_chat` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启聊天(0-否;1-是)',



  `is_live_goods_buy` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启商品购买(0-否;1-是)',



  `is_live_like` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否开启点赞(0-否;1-是)',



  `live_tips` varchar(255) DEFAULT NULL COMMENT '直播间欢迎语',



  `live_reconnect_number` tinyint NOT NULL DEFAULT '3' COMMENT '视频断流重连次数',



  `live_reconnect_interval_time` tinyint NOT NULL DEFAULT '3' COMMENT '视频重连间隔(秒)',



  `live_goods_explain_auto_close_time` int NOT NULL DEFAULT '10' COMMENT '讲解商品自动关闭时间(秒)',



  `live_start_time` datetime DEFAULT NULL COMMENT '开播时间',



  `live_end_time` datetime DEFAULT NULL COMMENT '下播时间',



  `sort` int NOT NULL DEFAULT '0' COMMENT '排序(越小越靠前)',



  `remark` varchar(255) DEFAULT NULL COMMENT '备注',



  `create_time` datetime DEFAULT NULL COMMENT '创建时间',



  `update_time` datetime DEFAULT NULL COMMENT '更新时间',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标识(0-正常;1-删除)',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `uk_room_no` (`room_no`) USING BTREE,



  UNIQUE KEY `uk_stream_name` (`stream_name`) USING BTREE,



  KEY `idx_status_sort` (`status`,`sort`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='直播间表';







