  `config_name` varchar(100) NOT NULL COMMENT '配置名称（管理后台展示用）',



  `config_value` text COMMENT '配置值',



  `value_type` varchar(20) NOT NULL DEFAULT 'string' COMMENT '值类型: string/number/boolean/json/image/text',



  `group_code` varchar(50) NOT NULL DEFAULT 'base' COMMENT '分组: base/theme/function/客服/分类/用户/分享/页面布局',



  `remark` varchar(500) DEFAULT NULL COMMENT '备注说明',



  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',



  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 1-启用, 0-禁用',



  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`),



  UNIQUE KEY `uk_config_key` (`config_key`)



