-- ----------------------------



-- Table structure for sys_msg_record



-- ----------------------------



DROP TABLE IF EXISTS `sys_msg_record`;



CREATE TABLE `sys_msg_record` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',



  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道编码',



  `msg_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息类型',



  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模板编码',



  `template_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '模板参数(JSON)',



  `receiver` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '接收人',



  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '发送内容',



  `status` tinyint NOT NULL DEFAULT '0' COMMENT '发送状态(0-发送中 1-发送成功 2-发送失败)',



  `error_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '错误信息',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_receiver` (`receiver`) USING BTREE,



  KEY `idx_status` (`status`) USING BTREE,



  KEY `idx_channel_code` (`channel_code`) USING BTREE,



  KEY `idx_create_time` (`create_time`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=493 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='消息记录表';







-- ----------------------------



-- Records of sys_msg_record



-- ----------------------------



BEGIN;











COMMIT;







-- ----------------------------



-- Table structure for sys_msg_template



-- ----------------------------



DROP TABLE IF EXISTS `sys_msg_template`;



CREATE TABLE `sys_msg_template` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',



  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模板编码',



  `template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模板名称',



  `template_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模板内容',



  `channel_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道编码',



  `third_template_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '第三方模板ID',



  `template_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '模板参数(JSON格式)',



  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(0-禁用 1-启用)',



  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `uk_template_code` (`template_code`) USING BTREE,



  KEY `idx_channel_code` (`channel_code`) USING BTREE,



  KEY `idx_status` (`status`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='消息模板表';







