-- Records of sys_msg_template



-- ----------------------------



BEGIN;


















COMMIT;







-- ----------------------------



-- Table structure for sys_region



-- ----------------------------



DROP TABLE IF EXISTS `sys_region`;



CREATE TABLE `sys_region` (



  `id` mediumint unsigned NOT NULL,



  `parent_id` mediumint unsigned DEFAULT NULL COMMENT '父级ID',



  `level` tinyint unsigned DEFAULT NULL COMMENT '层级',



  `area_code` bigint unsigned DEFAULT NULL COMMENT '行政代码',



  `zip_code` mediumint(6) unsigned zerofill DEFAULT '000000' COMMENT '邮政编码',



  `city_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '区号',



  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '名称',



  `short_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '简称',



  `merger_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '组合名',



  `pinyin` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '拼音',



  `py` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,



  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐含(0:不隐含，1：隐含)',



  `sort` tinyint DEFAULT '0' COMMENT '排序(默认升序)',



  `lng` decimal(10,6) DEFAULT '0.000000' COMMENT '经度',



  `lat` decimal(10,6) DEFAULT '0.000000' COMMENT '纬度',



  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `deleted` tinyint unsigned NOT NULL COMMENT '是否删除：1、是，0、否',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_lev` (`parent_id`,`level`) USING BTREE,



  KEY `index_lev` (`level`) USING BTREE



) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='中国行政地区表';







