DROP TABLE IF EXISTS `sys_role`;



CREATE TABLE `sys_role` (



  `id` bigint NOT NULL AUTO_INCREMENT,



  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '角色名称',



  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '角色编码',



  `sort` int DEFAULT NULL COMMENT '显示顺序',



  `status` tinyint DEFAULT '1' COMMENT '角色状态(1-正常；0-停用)',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除标识(0-未删除；1-已删除)',



  `data_scope` tinyint DEFAULT NULL COMMENT '数据权限(0-所有数据；1-部门及子部门数据；2-本部门数据；3-本人数据)',



  `create_time` datetime DEFAULT NULL COMMENT '更新时间',



  `update_time` datetime DEFAULT NULL COMMENT '创建时间',



  `system_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '系统类型',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `name` (`name`) USING BTREE



