DROP TABLE IF EXISTS `sys_user`;



CREATE TABLE `sys_user` (



  `id` int NOT NULL AUTO_INCREMENT,



  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '用户名',



  `nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '昵称',



  `gender` tinyint(1) DEFAULT '1' COMMENT '性别((1:男;2:女))',



  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '密码',



  `system_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '系统类型(PLATFORM:平台系统;SUPPLIER:供应商系统)',



  `dept_id` int DEFAULT NULL COMMENT '部门ID',



  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '用户头像',



  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '联系方式',



  `status` tinyint(1) DEFAULT '1' COMMENT '用户状态((1:正常;0:禁用))',



  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '用户邮箱',



  `deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除标识(0:未删除;1:已删除)',



  `create_time` datetime DEFAULT NULL COMMENT '创建时间',



  `update_time` datetime DEFAULT NULL COMMENT '更新时间',



  `create_by` bigint DEFAULT NULL COMMENT '创建人ID',



  `update_by` bigint DEFAULT NULL COMMENT '更新人ID',



  PRIMARY KEY (`id`) USING BTREE,



  UNIQUE KEY `login_name` (`username`) USING BTREE



