-- ----------------------------



DROP TABLE IF EXISTS `ums_address`;



CREATE TABLE `ums_address` (



  `id` bigint NOT NULL AUTO_INCREMENT,



  `member_id` bigint DEFAULT NULL COMMENT '会员ID',



  `country_id` int DEFAULT '0' COMMENT '国家区域ID',



  `country_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '中国' COMMENT '国家名称',



  `consignee_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '收货人姓名',



  `consignee_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '收货人联系方式',



  `province_id` int DEFAULT '0' COMMENT '省',



  `city_id` int DEFAULT '0' COMMENT '市',



  `area_id` int DEFAULT '0' COMMENT '区',



  `province_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '省份',



  `city_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '市',



  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '区',



  `detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '详细地址',



  `complete_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '完整地址',



  `zip_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '邮编',



  `defaulted` tinyint DEFAULT NULL COMMENT '是否默认地址',



  `alias` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '地址别名（家/公司/学校/自定义）',



  `lng` decimal(10,6) DEFAULT NULL COMMENT '经度',



  `lat` decimal(10,6) DEFAULT NULL COMMENT '纬度',



  `create_time` datetime DEFAULT NULL COMMENT '创建时间',



  `update_time` datetime DEFAULT NULL COMMENT '更新时间',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除 0否 1是',



  `invitation_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,



  PRIMARY KEY (`id`) USING BTREE



) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;










