  `asset_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '资产编码类型: POINT(积分), GOLD_BEAN(金豆), SILVER_BEAN(银豆), CONTRIBUTION(贡献值)',



