-- Table structure for ums_message



-- ----------------------------



DROP TABLE IF EXISTS `ums_message`;



CREATE TABLE `ums_message` (



  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',



  `member_id` bigint NOT NULL DEFAULT '0' COMMENT '会员ID',



  `title` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '消息标题',



  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '消息内容(HTML)',



  `type` tinyint NOT NULL DEFAULT '1' COMMENT '消息类型: 1-系统通知',



  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '已读状态: 0-未读, 1-已读',



  `user_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '用户删除: 0-正常, 1-已删除',



  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',



  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',



  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',



  PRIMARY KEY (`id`) USING BTREE,



  KEY `idx_member_read` (`member_id`,`is_read`) USING BTREE,



  KEY `idx_member_deleted` (`member_id`,`user_deleted`) USING BTREE



) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='会员消息表';







