INSERT INTO `sys_msg_template` (`id`, `template_code`, `template_name`, `template_content`, `channel_code`, `third_template_id`, `template_params`, `status`, `remark`, `create_time`, `update_time`) VALUES (1, 'LOGIN_SMS', '登录验证码', '您的验证码是：${code}。请不要把验证码泄露给其他人。', 'VEESING_SMS', 'SMS_123456789', '[{\"name\":\"code\",\"description\":\"验证码\"}]', 1, '登录验证码模板', '2025-02-19 21:00:59', '2026-06-22 08:43:28');
INSERT INTO `sys_msg_template` (`id`, `template_code`, `template_name`, `template_content`, `channel_code`, `third_template_id`, `template_params`, `status`, `remark`, `create_time`, `update_time`) VALUES (2, 'REGISTER_SMS', '注册验证码', '您的验证码是：${code}。请不要把验证码泄露给其他人。', 'VEESING_SMS', 'SMS_987654321', '[{\"name\":\"code\",\"description\":\"验证码\"}]', 1, '注册验证码模板', '2025-02-19 21:00:59', '2026-06-22 08:43:28');
INSERT INTO `sys_msg_template` (`id`, `template_code`, `template_name`, `template_content`, `channel_code`, `third_template_id`, `template_params`, `status`, `remark`, `create_time`, `update_time`) VALUES (13, 'SUPPLIER_WITHDRAWAL_APPLY_NOTIFY', '供应商提现申请通知', '## 供应商提现申请通知\n> 供应商：${supplierName}\n> 提现单号：${withdrawalNo}\n> 提现金额：<font color=\"warning\">${amount} 元</font>\n> 手续费：${fee} 元\n> 实际到账：<font color=\"info\">${actualAmount} 元</font>\n> 申请时间：${applyTime}\n> 开户银行：${bankName}\n> 银行账户：${bankAccount}', 'WECOM_BOT', NULL, '[{\"name\":\"supplierName\",\"description\":\"供应商名称\"},{\"name\":\"withdrawalNo\",\"description\":\"提现单号\"},{\"name\":\"amount\",\"description\":\"提现金额\"},{\"name\":\"fee\",\"description\":\"手续费\"},{\"name\":\"actualAmount\",\"description\":\"实际到账金额\"},{\"name\":\"applyTime\",\"description\":\"申请时间\"},{\"name\":\"bankName\",\"description\":\"开户银行\"},{\"name\":\"bankAccount\",\"description\":\"银行账户(脱敏)\"}]', 1, '供应商提现申请时推送企微通知', '2026-06-22 08:22:11', '2026-06-22 11:59:03');
INSERT INTO `sys_msg_template` (`id`, `template_code`, `template_name`, `template_content`, `channel_code`, `third_template_id`, `template_params`, `status`, `remark`, `create_time`, `update_time`) VALUES (17, 'PRICE_MANUAL_ALERT', '人工调价预警', '## <font color=\"warning\">⚠️ 人工调价预警</font>\n> 商品：<font color=\"info\">${spuName}</font>（SPU-${spuId}）\n> 类型：<font color=\"info\">${spuType}</font>\n\n<#list skus as sku>**SKU：${sku.name}（${sku.id}）**\n> 零售毛利率：<font color=\"info\">${sku.retailMargin}%</font>\n\n> 实际价格（人工）：\n> 供货价 ${sku.supply} / 批发价 <font color=\"warning\">${sku.manualWhole}</font> / 云仓价 <font color=\"warning\">${sku.manualWarehouse}</font> / 零售价 ${sku.retail}\n\n> 规则价格（公式）：\n> 供货价 ${sku.supply} / 批发价 <font color=\"info\">${sku.formulaWhole}</font> / 云仓价 <font color=\"info\">${sku.formulaWarehouse}</font> / 零售价 ${sku.retail}\n\n> 差异：<font color=\"warning\">${sku.diffDetail}</font>\n\n</#list>操作人：${operator}\n时间：${time}', 'WECOM_BOT', NULL, '[{\"name\":\"spuName\",\"description\":\"商品名称\"},{\"name\":\"spuId\",\"description\":\"商品ID\"},{\"name\":\"spuType\",\"description\":\"商品类型\"},{\"name\":\"skus\",\"description\":\"告警SKU列表（name,id,supply,retail,manualWarehouse,manualWhole,formulaWarehouse,formulaWhole,retailMargin,warehouseChanged,wholeChanged,diffDetail）\"},{\"name\":\"operator\",\"description\":\"操作人\"},{\"name\":\"time\",\"description\":\"告警时间\"}]', 0, '已移除人工云仓/批发调价预警，代码不再触发', '2026-06-22 10:21:52', '2026-10-12 11:20:00');
INSERT INTO `sys_msg_template` (`id`, `template_code`, `template_name`, `template_content`, `channel_code`, `third_template_id`, `template_params`, `status`, `remark`, `create_time`, `update_time`) VALUES (18, 'PRICE_ANOMALY_ALERT', '价格异常预警（零售毛利率）', '## <font color=\"warning\">⚠️ 价格异常预警</font>\n> 商品：<font color=\"info\">${spuName}</font>（SPU-${spuId}）\n> 类型：<font color=\"info\">${spuType}</font>\n\n<#list skus as sku>**SKU：${sku.name}（${sku.id}）**\n\n> 零售价毛利率：<font color=\"info\">${sku.retailMargin}%</font> <#if sku.retailBelow>❌<#else>✅</#if>（阈值 ${retailThreshold}%）\n\n> 当前：${sku.priceInfo}\n\n</#list>操作人：${operator}\n时间：${time}', 'WECOM_BOT', NULL, '[{\"name\":\"spuName\",\"description\":\"商品名称\"},{\"name\":\"spuId\",\"description\":\"商品ID\"},{\"name\":\"spuType\",\"description\":\"商品类型\"},{\"name\":\"retailThreshold\",\"description\":\"零售毛利率阈值\"},{\"name\":\"skus\",\"description\":\"告警SKU列表(数组)\"},{\"name\":\"operator\",\"description\":\"操作人\"},{\"name\":\"time\",\"description\":\"告警时间\"}]', 1, '仅校验零售毛利率', '2026-06-22 10:21:52', '2026-10-12 11:20:00');
